local CDV = {}
local ID = TEN.Objects.ObjID

-- Persistent state lives in LevelVars (saved with the game); always fetched through St().
local function St()
    if LevelVars.CDV == nil then
        LevelVars.CDV = { done = {}, flags = {}, secrets = {} }
    end
    return LevelVars.CDV
end
CDV.St = St

-- Riprese (trailer): Engine\Scripts\CdvRiprese.lua -> return { attivo = true, ciclo = false, solo = nil }
local okRip, RIP = pcall(require, "CdvRiprese")
if not okRip or type(RIP) ~= "table" then RIP = { attivo = false } end
CDV.RIP = RIP
CDV.SHOTS = 0      -- flyby sequences 1..SHOTS placed by tools/shots.py

local msg = nil
local msgTimer = 0

-- Captions: British English, only what the plot needs. Long text is broken into lines of at most CDV.WRAP characters
-- (so that nothing is cut at the sides) and a caption of several lines is lifted so that it stays on screen.
CDV.WRAP = 46
function CDV.Wrap(text, width)
    local lines, line = {}, ""
    for word in tostring(text):gmatch("%S+") do
        if #line > 0 and #line + 1 + #word > width then
            lines[#lines + 1] = line
            line = word
        else
            line = (#line > 0) and (line .. " " .. word) or word
        end
    end
    if #line > 0 then lines[#lines + 1] = line end
    return table.concat(lines, "\n"), #lines
end
function CDV.Say(text, seconds)
    if RIP.attivo then return end
    if text == nil or text == "" then return end
    -- A caption is shown once in the whole game: once on screen it counts as read and never comes back.
    -- Remembered in GameVars (kept through levels and saved games) under a short key made from the text.
    local h = 5381
    for i = 1, #text do h = (h * 33 + text:byte(i)) % 2147483647 end
    local key = "c" .. h
    if GameVars.CDV_read == nil then GameVars.CDV_read = {} end
    if GameVars.CDV_read[key] then return end
    GameVars.CDV_read[key] = true
    if msg ~= nil then
        TEN.Strings.HideString(msg)
    end
    local wrapped, n = CDV.Wrap(text, CDV.WRAP)
    local x, y = TEN.Util.PercentToScreen(50, 86 - 4.2 * math.max(1, n))
    msg = TEN.Strings.DisplayString(wrapped, TEN.Vec2(x, y), 0.8, TEN.Color(255, 244, 214), false,
        { TEN.Strings.DisplayStringOption.CENTER, TEN.Strings.DisplayStringOption.SHADOW })
    TEN.Strings.ShowString(msg, seconds or 6)
end

function CDV.M(name)
    local ok, m = pcall(TEN.Objects.GetMoveableByName, name)
    if ok then return m end
    return nil
end

function CDV.Dead(name)
    local m = CDV.M(name)
    if m == nil then return true end
    if not m:GetValid() then return true end
    return m:GetHP() <= 0
end

function CDV.Active(name)
    local m = CDV.M(name)
    return m ~= nil and m:GetValid() and m:GetActive()
end

-- Levers (wall levers, SWITCH_TYPE4) toggle between two states: "pulled" = not in the state it had at start.
function CDV.Pulled(name)
    local m = CDV.M(name)
    if m == nil or not m:GetValid() then return false end
    local k = "s0_" .. name
    local s0 = CDV.Flag(k)
    if s0 == nil then
        s0 = m:GetState()
        CDV.Flag(k, s0)
    end
    return m:GetState() ~= s0
end

-- Two levers to be pulled within `frames` of each other (TEN levers toggle, so every pull is an event:
-- a late player simply pulls one again). Solved once; fn runs then.
function CDV.TwinLevers(id, a, b, frames, msgFirst, msgLate, fn)
    CDV.Loop(function()
        if CDV.Flag(id .. "_ok") then return end
        local now = (CDV.Flag(id .. "_t") or 0) + 1
        CDV.Flag(id .. "_t", now)
        for _, n in ipairs({a, b}) do
            local m = CDV.M(n)
            if m ~= nil and m:GetValid() then
                if CDV.Used(n) then
                    CDV.Rearm(n)
                    local other = (n == a) and b or a
                    local to = CDV.Flag(id .. "_e_" .. other)
                    if to ~= nil and now - to <= frames then
                        CDV.Flag(id .. "_ok", true)
                        fn()
                        return
                    end
                    CDV.Flag(id .. "_e_" .. n, now)
                    if to ~= nil then CDV.Say(msgLate, 5) else CDV.Say(msgFirst, 4) end
                end
            end
        end
    end)
end

function CDV.Enable(name)
    local m = CDV.M(name)
    if m ~= nil and m:GetValid() then m:Enable() end
end

function CDV.Disable(name)
    local m = CDV.M(name)
    if m ~= nil and m:GetValid() then m:Disable() end
end

-- Run fn after a number of frames (30 = 1 s). Not saved: use only for short visual sequences.
local timers = {}
function CDV.After(frames, fn) timers[#timers + 1] = { t = frames, fn = fn } end
-- An earthquake that can be seen: strength s*5 (150 at most) held for s*2 frames, then the engine lets it die away.
function CDV.Quake(s)
    local n, str = s * 2, math.min(150, s * 5)
    local function go()
        pcall(function() TEN.Effects.MakeEarthquake(str) end)
        n = n - 1
        if n > 0 then CDV.After(1, go) end
    end
    go()
end

local function TimersTick()
    for i = #timers, 1, -1 do
        local t = timers[i]
        t.t = t.t - 1
        if t.t <= 0 then table.remove(timers, i); t.fn() end
    end
end

-- Key into a lock moveable, scripted: Lara steps to the plate, plays the native "use key" animation,
-- then the target (a door) is enabled as if triggered.
function CDV.InsertKey(lockName, targetName, leafName)
    local lock = CDV.M(lockName)
    if lock ~= nil and lock:GetValid() then
        local lp = lock:GetPosition()
        local yaw = lock:GetRotation().y
        local a = math.rad(yaw)
        Lara:SetPosition(TEN.Vec3(lp.x + math.sin(a) * 312, lp.y, lp.z + math.cos(a) * 312), false)
        Lara:SetRotation(TEN.Rotation(0, yaw, 0))
        Lara:SetAnim(131)
        Lara:SetState(42)
    end
    CDV.After(45, function()
        CDV.Enable(targetName)
        if leafName then CDV.Swing(leafName, "y", 90, 40) end
    end)
end

-- Turn a named static about its own origin (hinged leaves and hatches): axis "x", "y" or "z",
-- `by` degrees over `frames` frames.
function CDV.Swing(name, axis, by, frames)
    local ok, st = pcall(TEN.Objects.GetStaticByName, name)
    if not ok or st == nil then return end
    local r0 = st:GetRotation()
    local start = { x = r0.x, y = r0.y, z = r0.z }
    local f = 0
    local function step()
        f = f + 1
        local t = math.min(f / frames, 1.0)
        local r = { x = start.x, y = start.y, z = start.z }
        r[axis] = start[axis] + by * (1 - (1 - t) * (1 - t))
        st:SetRotation(TEN.Rotation(r.x, r.y, r.z))
        if f < frames then CDV.After(1, step) end
    end
    CDV.After(1, step)
end

-- Hands: a key or a device is never used with a weapon drawn. Lara puts it away first.
function CDV.HandsFree()
    local ok, free = pcall(function() return Lara:GetHandStatus() == TEN.Objects.HandStatus.FREE end)
    return (not ok) or free
end
function CDV.Holster()
    pcall(function() Lara:UndrawWeapon() end)
end

-- With a weapon in her hands Lara does not work doors, locks or devices (Ed, 14/11): nothing happens.
local armedSaid = -1000
local armedClock = 0
function CDV.Armed()
    if armedClock - armedSaid > 240 then
        armedSaid = armedClock
        CDV.Say("Holster your weapons first.", 3)
    end
end

-- The «insert» animation (LA_USE_PUZZLE, 134, state 43). Its frame 80 runs flip effect 13 (Puzzle), which crashes
-- when no puzzle hole of the engine is involved: that frame is skipped. Her item flag 0 (the animation the engine
-- would jump to at the end) is kept at zero.
function CDV.PuzzleAnim()
    pcall(function() Lara:SetItemFlags(0, 0) end)
    Lara:SetAnim(134)
    Lara:SetState(43)
    local n = 0
    local function guard()
        n = n + 1
        if n > 400 or Lara:GetAnim() ~= 134 then return end
        local f = Lara:GetFrame()
        if f >= 77 and f <= 80 then
            if not pcall(function() Lara:SetFrame(81) end) or Lara:GetFrame() ~= 81 then
                Lara:SetAnim(103)          -- no frame 81 in this Lara: stand, rather than reach frame 80
                Lara:SetState(2)
                return
            end
        end
        CDV.After(1, guard)
    end
    guard()
end

-- Classic keyhole behaviour without a floor trigger: Lara in front of the lock plate, facing it,
-- presses Action while holding the key -> the inventory opens on that key (using it there runs the
-- CDV.Use entry of the lock). The lock's position is read at run time, so it can be moved in the editor.
function CDV.KeyPrompt(lockName, item, doneId)
    if doneId and CDV.Done(doneId) then return end
    if not CDV.Has(item) then return end
    if not TEN.Input.IsKeyHit(TEN.Input.ActionID.ACTION) then return end
    if Lara:GetState() ~= 2 then return end          -- standing still, on the ground
    local lock = CDV.M(lockName)
    if lock == nil or not lock:GetValid() then return end
    local lp, p = lock:GetPosition(), Lara:GetPosition()
    local armed = not CDV.HandsFree()
    local a = math.rad(lock:GetRotation().y)
    local dx, dz = p.x - lp.x, p.z - lp.z
    local side = dx * math.cos(a) - dz * math.sin(a)
    local ahead = dx * math.sin(a) + dz * math.cos(a)
    local dyaw = math.abs(((Lara:GetRotation().y - lock:GetRotation().y) + 540) % 360 - 180)
    if math.abs(side) < 220 and ahead > 60 and ahead < 520 and math.abs(p.y - lp.y) < 400 and dyaw < 35 then
        if armed then CDV.Armed() return end
        TEN.Inventory.SetFocusedItem(item)
    end
end

-- Same as KeyPrompt for a static device (no moveable to read): Action within r of the point opens the
-- inventory on the item, when Lara has it.
function CDV.KeyPromptAt(x, y, z, r, item, doneId)
    if doneId and CDV.Done(doneId) then return end
    if not TEN.Input.IsKeyHit(TEN.Input.ActionID.ACTION) then return end
    if not CDV.Near(x, y, z, r, 700) then return end
    if not CDV.FrontOk(doneId) then return end
    if not CDV.Has(item) then return end
    if Lara:GetState() ~= 2 then return end          -- standing still, on the ground
    if not CDV.HandsFree() then CDV.Armed() return end
    TEN.Inventory.SetFocusedItem(item)
end

function CDV.Has(item)
    return TEN.Inventory.GetItemCount(item) > 0
end

function CDV.Give(item, count)
    TEN.Inventory.GiveItem(item, count or 1, true)
end

function CDV.Take(item)
    TEN.Inventory.TakeItem(item, 1)
end

function CDV.Near(x, y, z, r, dy)
    local p = Lara:GetPosition()
    local dx, dz = p.x - x, p.z - z
    if dx * dx + dz * dz > r * r then return false end
    return math.abs(p.y - y) <= (dy or 1536)
end


-- 20 Nov: keys only from in front of the lock.
CDV.FRONTS = CDV.FRONTS or {}
local function CdvFront(f)
    if f.lock then
        local m = CDV.M(f.lock)
        if m == nil or not m:GetValid() then return nil end
        local q, yaw = m:GetPosition(), m:GetRotation().y
        local a = math.rad(yaw)
        return q.x + math.sin(a) * 312, q.z + math.cos(a) * 312, yaw, true
    end
    return f.x, f.z, f.yaw, false
end
function CDV.FrontOk(id)
    local f = id and CDV.FRONTS[id]
    if f == nil then return true end
    local x, z, yaw, lock = CdvFront(f)
    if x == nil then return true end
    local p = Lara:GetPosition()
    local turn = math.abs(((Lara:GetRotation().y - yaw) + 540) % 360 - 180)
    if turn > (f.turn or 40) then
        CDV.Log("FRONT " .. tostring(id) .. ": not facing the lock, off by " .. math.floor(turn))
        return false
    end
    if lock then                                   -- a keyhole object: the same window as CDV.KeyPrompt
        local a = math.rad(yaw)
        local dx, dz = p.x - (x - math.sin(a) * 312), p.z - (z - math.cos(a) * 312)
        local side = dx * math.cos(a) - dz * math.sin(a)
        local ahead = dx * math.sin(a) + dz * math.cos(a)
        return math.abs(side) < 220 and ahead > 60 and ahead < 520
    end
    -- 20 Nov, 14:20: a strip in front of the lock, not a circle round the spot where she is put: a player walks
    -- right up to the wall, and that was outside the circle (the padlock of the hatch could not be opened).
    local a = math.rad(yaw)
    local dx, dz = p.x - x, p.z - z
    local side = dx * math.cos(a) - dz * math.sin(a)
    local ahead = dx * math.sin(a) + dz * math.cos(a)          -- positive: nearer the lock than the spot
    local ok = math.abs(side) <= (f.side or 260) and ahead >= -(f.back or 300) and ahead <= 450
    if not ok then CDV.Log("FRONT " .. tostring(id) .. ": side " .. math.floor(side) .. " ahead " .. math.floor(ahead)) end
    return ok
end
function CDV.FrontSnap(id)
    local f = id and CDV.FRONTS[id]
    if f == nil or f.lock then return end
    local p = Lara:GetPosition()
    Lara:SetPosition(TEN.Vec3(math.floor(f.x), p.y, math.floor(f.z)), false)
    Lara:SetRotation(TEN.Rotation(0, f.yaw, 0))
end
CDV.STAR_REWARD = { { ID.BIGMEDI_ITEM, 2 }, { ID.SMALLMEDI_ITEM, 3 }, { ID.SHOTGUN_AMMO1_ITEM, 3 }, { ID.HK_AMMO_ITEM, 2 }, { ID.ROCKET_LAUNCHER_AMMO_ITEM, 2 } }
CDV.STAR_TEXT = "All three Stars of the lost half. The Twins repay the favour: medipacks, shells, rounds, rockets."

function CDV.Done(id)
    return St().done[id] == true
end

function CDV.Flag(name, value)
    local S = St()
    if value ~= nil then S.flags[name] = value end
    return S.flags[name]
end

-- Teleport with a short fade (used for building doors that cannot be wall portals).
local tp = nil
function CDV.Teleport(x, y, z, roomName, yaw)
    if tp ~= nil then return end
    tp = { x = x, y = y, z = z, room = roomName, yaw = yaw, t = 0 }
    TEN.View.FadeOut(4)
end

local function TeleportStep()
    if tp == nil then return end
    tp.t = tp.t + 1
    if tp.t == 10 then
        Lara:SetPosition(TEN.Vec3(tp.x, tp.y, tp.z), false)
        local room = TEN.Objects.GetRoomByName(tp.room)
        if room ~= nil then Lara:SetRoomNumber(room:GetRoomNumber()) end
        if tp.yaw ~= nil then Lara:SetRotation(TEN.Rotation(0, tp.yaw, 0)) end
    elseif tp.t >= 12 then
        TEN.View.FadeIn(4)
        tp = nil
    end
end

local zones, uses, drops, secrets, loops = {}, {}, {}, {}, {}

-- zone {id, x, y, z, r, dy, once, need, fn}
function CDV.Zone(z) zones[#zones + 1] = z end
-- use {id, item, x, y, z, r, dy, consume, need, fn, fail}
function CDV.Use(u) uses[#uses + 1] = u end
-- drop {id, enemy, item, text}
function CDV.Drop(d) drops[#drops + 1] = d end
-- secret {index, x, y, z, r}
function CDV.Secret(s) secrets[#secrets + 1] = s end
-- loop function called every frame
function CDV.Loop(f) loops[#loops + 1] = f end

-- Full-screen video from Engine\FMV (mp4/mkv/mov/avi). A missing file only writes a warning in the log.
function CDV.Video(name)
    if RIP.attivo then return end
    TEN.View.PlayVideo(name)
end

local rip = { t = 0, cur = 0, wait = 60 }
local function RipreseTick()
    if not RIP.attivo or CDV.SHOTS == 0 then return end
    if TEN.View.GetCameraType() == TEN.View.CameraType.FLYBY then
        rip.wait = 45
        return
    end
    if rip.wait > 0 then
        rip.wait = rip.wait - 1
        return
    end
    local first = RIP.solo or 1
    local last = RIP.solo or CDV.SHOTS
    if rip.cur == 0 then
        rip.cur = first
    else
        rip.cur = rip.cur + 1
        if rip.cur > last then
            if not RIP.ciclo then
                rip.cur = last + 1
                rip.wait = 1e9
                return
            end
            rip.cur = first
        end
    end
    TEN.View.PlayFlyby(rip.cur)
end
CDV.RipreseTick = RipreseTick

function CDV.Tick()
    armedClock = armedClock + 1
    local S = St()
    TimersTick()
    RipreseTick()
    TeleportStep()
    for _, z in ipairs(zones) do
        if not (z.once and S.done[z.id]) then
            if (z.need == nil or z.need()) and CDV.Near(z.x, z.y, z.z, z.r, z.dy) then
                if z.once then S.done[z.id] = true end
                if z.text then CDV.Say(z.text, z.secs) end
                CDV.Cue(z.id)
                if z.fn then z.fn() end
            end
        end
    end
    for _, d in ipairs(drops) do
        if not S.done["drop_" .. d.id] and CDV.Dead(d.enemy) then
            S.done["drop_" .. d.id] = true
            CDV.Cue("drop_" .. d.id)
            CDV.Give(d.item, 1)
            if d.text then CDV.Say(d.text, 6) end
        end
    end
    -- A secret is a Star of the Dioscuri lying at its place ("stella_<index>", PUZZLE_ITEM16): it is found when she
    -- picks the star up. The star goes out of the inventory at once; until then it glimmers when she is near.
    -- In a level compiled without the stars a secret is still found by walking onto its place.
    local stars = false
    for _, s in ipairs(secrets) do
        if CDV.M("stella_" .. s.index) ~= nil then stars = true end
    end
    local function found(s)
        S.secrets["s" .. s.index] = true
        TEN.Flow.AddSecret(s.index)
        CDV.Cue("segreto")
        CDV.Say(s.text or "", 5)
        if s.give then CDV.Give(s.give, 1) end
        local all = true
        for _, q in ipairs(secrets) do if not S.secrets["s" .. q.index] then all = false end end
        if all and CDV.STAR_REWARD and not S.done["premio_stelle"] then      -- 20 Nov: every Star of the level
            S.done["premio_stelle"] = true
            for _, g in ipairs(CDV.STAR_REWARD) do CDV.Give(g[1], g[2]) end
            CDV.After(120, function() CDV.Say(CDV.STAR_TEXT, 7) end)
        end
    end
    if stars then
        local lp = Lara:GetPosition()
        local ok, got = pcall(TEN.Inventory.GetItemCount, ID.PUZZLE_ITEM16)
        if ok and got ~= nil and got > 0 then
            pcall(TEN.Inventory.TakeItem, ID.PUZZLE_ITEM16, got)
            local best, bd = nil, 1e18
            for _, s in ipairs(secrets) do
                local d = (lp.x - s.x) ^ 2 + (lp.y - s.y) ^ 2 + (lp.z - s.z) ^ 2
                if not S.secrets["s" .. s.index] and d < bd then best, bd = s, d end
            end
            if best ~= nil then found(best) end
        end
        CDV.starTick = (CDV.starTick or 0) + 1
        for _, s in ipairs(secrets) do
            if not S.secrets["s" .. s.index] and math.abs(lp.x - s.x) < 10240 and math.abs(lp.z - s.z) < 10240 then
                local k = 0.6 + 0.4 * math.sin(CDV.starTick / 9)
                pcall(function()
                    TEN.Effects.EmitLight(TEN.Vec3(s.x, s.y - 160, s.z), TEN.Color(math.floor(210 * k), math.floor(225 * k), math.floor(255 * k)), 5, false, "cdv_stella_" .. s.index)
                end)
            end
        end
    else
        for _, s in ipairs(secrets) do
            if not S.secrets["s" .. s.index] and CDV.Near(s.x, s.y, s.z, s.r, 1024) then found(s) end
        end
    end
    for _, f in ipairs(loops) do f() end
end

function CDV.UseItem(again)
    local S = St()
    local item = again or TEN.Inventory.GetUsedItem()
    if Lara:GetState() ~= 2 then                     -- in the air, running, climbing: nothing is used
        for _, u in ipairs(uses) do
            if item == u.item then TEN.Inventory.ClearUsedItem() return end
        end
    end
    if not CDV.HandsFree() then
        for _, u in ipairs(uses) do
            if item == u.item then          -- weapon in hand: refused
                TEN.Inventory.ClearUsedItem()
                CDV.Armed()
                return
            end
        end
    end
    for _, u in ipairs(uses) do
        local ux, uy, uz = u.x, u.y, u.z
        if u.near then
            local m = CDV.M(u.near)
            if m ~= nil and m:GetValid() then local q = m:GetPosition(); ux, uy, uz = q.x, q.y, q.z end
        end
        if item == u.item and not S.done["use_" .. u.id] and CDV.Near(ux, uy, uz, u.r, u.dy) and CDV.FrontOk("use_" .. u.id) then
            if u.need == nil or u.need() then
                TEN.Inventory.ClearUsedItem()
                S.done["use_" .. u.id] = true
                if u.consume then CDV.Take(u.item) end
                if u.text then CDV.Say(u.text, u.secs or 7) end
                CDV.CueAfterAnim("use_" .. u.id)
                CDV.FrontSnap("use_" .. u.id)
                if u.fn then u.fn() end
                return
            elseif u.fail then
                TEN.Inventory.ClearUsedItem()
                CDV.Say(u.fail, 6)
                return
            end
        end
    end
end

-- Audio: a file Engine\\Audio\\<name>.wav (or .ogg, .mp3). A missing file is not an error for the game.
