CDV.KEY = "Sommersa"
CDV.VIDEO = "cdv_06_sommersa"

-- A model that is shown only once Lara has put the thing there (with her "use" animation).
function CDV.Put(name)
    CDV.InsertItem(nil, function() CDV.ShowModel(name, true) end)
end
-- Lara puts something in its place: the "insert" animation (LA_USE_PUZZLE, 134), then fn when her hand comes away;
-- mid() runs half way (the thing showing up). The engine jumps to the animation written in her item flag 0 at the
-- last frame: it is kept at zero. If this ever crashes, CDV.USE_PUZZLE_ANIM = false goes back to the key animation.
CDV.USE_PUZZLE_ANIM = true           -- 134 with its frame 80 skipped (CDV.PuzzleAnim)
function CDV.InsertItem(fn, mid, key)          -- key = true: a key is turned (131), not a thing fitted in (134)
    local anim = (CDV.USE_PUZZLE_ANIM and not key) and 134 or 131
    if anim == 134 then CDV.PuzzleAnim() else Lara:SetAnim(131); Lara:SetState(42) end
    local n = 0
    local function wait()
        n = n + 1
        if mid and (n >= (anim == 134 and 82 or 109) or (Lara:GetAnim() == anim and Lara:GetFrame() >= (anim == 134 and 76 or 103))) then
            mid()          -- on the click of the animation (its sound command), not before
            mid = nil
        end
        if n < 240 and (n < 45 or Lara:GetAnim() == anim) then CDV.After(1, wait); return end
        if mid then mid() end
        if fn then fn() end
    end
    CDV.After(1, wait)
end
-- A thing taken from a low pedestal: Lara's own pickup (LA_PICKUP_PEDESTAL_LOW, 425, state 39). mid() when her hand
-- closes on it (frame 29, where the animation has its pickup command), fn() at the end.
function CDV.PickItem(fn, mid)
    Lara:SetAnim(425)
    Lara:SetState(39)
    local n = 0
    local function wait()
        n = n + 1
        if mid and (n >= 36 or (Lara:GetAnim() == 425 and Lara:GetFrame() >= 29)) then
            mid()
            mid = nil
        end
        if n < 240 and (n < 20 or Lara:GetAnim() == 425) then CDV.After(1, wait); return end
        if mid then mid() end
        if fn then fn() end
    end
    CDV.After(1, wait)
end
function CDV.Flyby(seq)
    CDV.Log("FLYBY " .. seq)
    pcall(function() TEN.View.PlayFlyby(seq) end)
end
-- A bronze wheel on a wall (KEY_HOLE7): Action in front of it, Lara turns it half a turn, then fn. ok() says
-- whether it can still be turned.
function CDV.Wheel(name, ok, fn)
    local busy = false
    CDV.Loop(function()
        if busy or not ok() then return end
        local m = CDV.M(name)
        if m == nil or not m:GetValid() then return end
        if not TEN.Input.IsKeyHit(TEN.Input.ActionID.ACTION) or Lara:GetState() ~= 2 then return end
        local p, r0 = m:GetPosition(), m:GetRotation()
        local a = math.rad(r0.y)
        local sx, sz = p.x - math.sin(a) * 400, p.z - math.cos(a) * 400
        local lp = Lara:GetPosition()
        if (lp.x - sx) ^ 2 + (lp.z - sz) ^ 2 > 420 ^ 2 or math.abs(lp.y - (p.y + 620)) > 300 then return end
        if not CDV.HandsFree() then CDV.Armed() return end
        busy = true
        Lara:SetPosition(TEN.Vec3(math.floor(sx), lp.y, math.floor(sz)), false)
        Lara:SetRotation(TEN.Rotation(0, r0.y, 0))
        Lara:SetAnim(470)
        Lara:SetState(40)
        local f = 0
        local function step()
            f = f + 1
            if f > 40 and f <= 150 then
                pcall(function() m:SetRotation(TEN.Rotation(r0.x, r0.y, (r0.z + 180 * (f - 40) / 110) % 360)) end)
            end
            if f < 220 and (f < 152 or Lara:GetAnim() == 470) then CDV.After(1, step); return end
            busy = false
            fn()
        end
        CDV.After(1, step)
    end)
end

