local function Drown(name)
    local m = CDV.M(name)
    if m ~= nil and m:GetValid() and CDV.Active(name) and m:GetHP() > 0 then m:SetHP(0) return true end
    return false
end
local function SetWater(on)
    if (CDV.Flag("acqua") or false) == on then return end
    TEN.Flow.FlipMap(1)
    CDV.Flag("acqua", on)
    if on then
        Drown("g1")
        Drown("g2")
        if CDV.Flag("turi_sveglio") and not CDV.Flag("turi_morto") then
            CDV.After(120, function()
                Drown("turi")
                CDV.Flag("turi_morto", true)
            end)
        end
        CDV.Enable("squalo")
    else
        for _, nm in ipairs({ "squalo", "squalo2", "squalo3" }) do
            local q = CDV.M(nm)
            if q ~= nil and q:GetValid() and q:GetHP() <= 0 then
                -- a dead one: with the water gone it lies on the floor, not in mid-air
                local ok, how = pcall(function()
                    local qp = q:GetPosition()
                    local fl = TEN.Collision.Probe(qp, q:GetRoomNumber()):GetFloorHeight()
                    if fl ~= nil and fl > qp.y then
                        q:SetPosition(TEN.Vec3(qp.x, fl - 100, qp.z), false)
                        return "on the floor, y " .. fl
                    end
                    q:SetPosition(TEN.Vec3(qp.x, qp.y + 30000, qp.z), false)
                    return "out of sight"
                end)
                CDV.Log("SHARK " .. nm .. " dead, water gone: " .. tostring(how))
            elseif nm == "squalo" then
                CDV.Disable("squalo")
            end
        end
        if CDV.Flag("leva_valve") and not CDV.Flag("valve_aperte") then
            CDV.Flag("valve_aperte", true)
            CDV.Enable("porta_valve")
            CDV.Sfx(105)
            CDV.Say("With the weight of the water gone, the bronze doors at the end of the cella open.", 6)
        end
    end
end
-- Lara in the water: swimming under it or on it (her state), or standing in a room of water.
local WATER_STATES = { [13] = true, [17] = true, [18] = true, [33] = true, [34] = true, [35] = true, [44] = true,
    [47] = true, [48] = true, [49] = true }
function CDV.InWater()
    if WATER_STATES[Lara:GetState()] then return true end
    local ok, w = pcall(function() return Lara:GetRoom():GetFlag(TEN.Objects.RoomFlagID.WATER) end)
    return ok and w == true
end

-- Spirits that come one at a time. c = { id, names = {...}, colors = {{r, g, b}...}, start = function -> bool,
-- gone = function(k), done = function() }. Spirit k comes out; it dies when Lara has been in the water for a second
-- and a half with it out (the engine only kills a wraith when the camera is under water, which is why it used to
-- depend on where Lara was); the next one comes when she has been out of the water for a second and a half, or
-- after ten seconds anyway. Nothing here depends on where in the room Lara is.
function CDV.Spirits(c)
    local P = c.id
    CDV.Loop(function()
        if CDV.Flag(P .. "_fine") or not c.start() then return end
        local k = CDV.Flag(P .. "_k") or 0
        local out = CDV.Flag(P .. "_fuori") == true
        local t = (CDV.Flag(P .. "_t") or 0) + 1
        local wet = CDV.InWater()
        if not out then
            local dry = wet and 0 or ((CDV.Flag(P .. "_asciutta") or 0) + 1)
            CDV.Flag(P .. "_asciutta", dry)
            if (k == 0 and t > (c.first or 30)) or (k > 0 and (dry >= 45 or t > 300)) then
                k = k + 1
                local name = c.names[k]
                CDV.ShowModel(name, true)
                CDV.Enable(name)
                local m = CDV.M(name)
                local col = c.colors[k]
                if m ~= nil and m:GetValid() then
                    local q = m:GetPosition()
                    CDV.Glow({ { q.x, q.y, q.z } }, col[1], col[2], col[3], 50, 20)      -- it comes out of the stone
                end
                CDV.Sfx(184)
                CDV.Log("SPIRIT " .. P .. " " .. k .. " out")
                CDV.Flag(P .. "_k", k)
                CDV.Flag(P .. "_fuori", true)
                CDV.Flag(P .. "_acqua", 0)
                t = 0
            end
        else
            local name = c.names[k]
            local w = (CDV.Flag(P .. "_acqua") or 0) + (wet and 1 or 0)
            CDV.Flag(P .. "_acqua", w)
            local m = CDV.M(name)
            local q = (m ~= nil and m:GetValid()) and m:GetPosition() or Lara:GetPosition()
            local dead = t > 60 and not CDV.Active(name)          -- the engine put it out by itself
            if not dead and t > 60 and w >= 45 then
                CDV.Disable(name)
                dead = true
            end
            if dead then
                local col = c.colors[k]
                CDV.ShowModel(name, false)
                CDV.Glow({ { q.x, q.y, q.z } }, col[1], col[2], col[3], 40, 24)
                CDV.Sfx(105)
                CDV.Log("SPIRIT " .. P .. " " .. k .. " gone, water frames " .. w .. ", out for " .. t)
                CDV.Flag(P .. "_fuori", false)
                CDV.Flag(P .. "_asciutta", 0)
                t = 0
                if c.gone then c.gone(k) end
                if k >= #c.names then
                    CDV.Flag(P .. "_fine", true)
                    CDV.Log("SPIRITS " .. P .. " all gone")
                    if c.done then c.done() end
                end
            end
        end
        CDV.Flag(P .. "_t", t)
    end)
end

-- The altar of the Stars (two sockets, Castor's on the left). Lara is put in front of the socket, facing it.
local ALTAR_Z, SOCKET_C, SOCKET_P = 28833, 48332, 48947
local altarBusy = false
local function AtAltar()
    local p = Lara:GetPosition()
    return math.abs(p.x - 48640) < 760 and p.z > 28000 and p.z < 28960 and math.abs(p.y) < 300
end
local function FaceAltar(x)
    local lp = Lara:GetPosition()
    Lara:SetPosition(TEN.Vec3(x, lp.y, ALTAR_Z), false)
    Lara:SetRotation(TEN.Rotation(0, 0, 0))
end
-- Castor's Star: Action sets it (the sea comes in) or takes it back (it goes). Once Turi is dead, or his Star is in
-- Lara's hands, it has fused with the altar and stays there.
local function CastorFused() return CDV.Flag("turi_morto") == true or CDV.Has(ID.PUZZLE_ITEM8) end
CDV.Loop(function()
    if altarBusy or CDV.Flag("fuga") then return end
    if not TEN.Input.IsKeyHit(TEN.Input.ActionID.ACTION) or Lara:GetState() ~= 2 then return end
    if not AtAltar() then return end
    local on = not CDV.Flag("acqua")
    if on and not CDV.Has(ID.PUZZLE_ITEM7) then return end
    if not on and CastorFused() then return end
    if not CDV.HandsFree() then CDV.Armed() return end
    altarBusy = true
    FaceAltar(SOCKET_C)
    CDV.Log("ALTAR Castor " .. (on and "set" or "taken back"))
    ;(on and CDV.InsertItem or CDV.PickItem)(function()              -- set: the insert; taken back: a pickup
        CDV.Sfx(238)
        CDV.Quake(on and 20 or 8)
        pcall(function() TEN.View.FadeOut(1.4) end)
        CDV.After(35, function()
            SetWater(on)
            pcall(function() TEN.View.FadeIn(1.0) end)
            if on and not CDV.Flag("detto_acqua") then
                CDV.Flag("detto_acqua", true)
                CDV.Say("The sea fills the cella. While the Star stays on the altar, so does the water.", 6)
            end
            altarBusy = false
        end)
    end, function()
        if on then CDV.Take(ID.PUZZLE_ITEM7) else CDV.Give(ID.PUZZLE_ITEM7, 1) end
        CDV.ShowModel("astro_c_posto", on)
    end)
end)
CDV.Loop(function()
    -- the lever of the bronze doors, on the east gallery
    if not CDV.Flag("leva_valve") and CDV.Used("leva_valve") then
        CDV.Flag("leva_valve", true)
        CDV.Sfx(114)
        CDV.Say("Down below, the bronze doors unlock. But they will never open against all that water.", 7)
    end
    -- Turi (the engine's TONY_BOSS) stands at the end of the cella when Lara comes down the stair; the engine
    -- wakes him when Lara comes within four sectors (item flag 3 leaves 0), and that is when his music starts.
    if CDV.Flag("valve_aperte") and not CDV.Flag("turi_visto") and not CDV.Flag("acqua") then
        local lp = Lara:GetPosition()
        if lp.y > 1200 and lp.x > 49000 and lp.x < 62600 and lp.z > 22000 and lp.z < 27700 then      -- on her way down the stair
        CDV.Flag("turi_visto", true)
        CDV.Enable("turi")
        CDV.Log("TURI stands in the cella")
        end
    end
    if CDV.Flag("turi_visto") and not CDV.Flag("turi_morto") then
        local m = CDV.M("turi")
        if m ~= nil and m:GetValid() and m:GetActive() then
            local awake = false
            pcall(function() awake = m:GetItemFlags(3) ~= 0 end)
            if not CDV.Flag("turi_sveglio") and (awake or CDV.Near(61952, 4096, 25088, 3600, 900)) then
                CDV.Flag("turi_sveglio", true)
                CDV.Cue("turi")
                CDV.Say("Turi 'a Vulpi, the Star of Pollux round his neck. Pollux is the immortal one: bullets will not stop him.", 8)
                CDV.Log("TURI wakes")
            end
            -- the Star of Pollux: while the cella is dry nothing kills him
            if not CDV.Flag("acqua") and m:GetHP() > 0 and m:GetHP() < 20000 then
                local phase = 0
                pcall(function() phase = m:GetItemFlags(3) end)
                if phase == 2 then m:SetHP(30000) end
            end
        end
    end
    -- his fire sets Lara alight: it dies by itself after a second and a half (in the sea at once, as always)
    local burning = false
    pcall(function() burning = Lara:GetEffect() == TEN.Effects.EffectID.FIRE end)
    if burning then
        CDV.Burn = (CDV.Burn or 0) + 1
        if CDV.Burn == 1 then CDV.Log("FIRE on Lara") end
        if CDV.Burn > 45 then
            pcall(function() Lara:SetEffect(TEN.Effects.EffectID.NONE) end)
            CDV.Burn = 0
        end
    else
        CDV.Burn = 0
    end
    -- the fall of the temple
    local t = CDV.Flag("fuga_t") or 0
    if t > 0 then
        t = t - 1
        CDV.Flag("fuga_t", t)
        if t % 40 == 0 then CDV.Quake(14) end
        if t == 0 then Lara:SetHP(0) end
    end
end)

-- Turi 'a Vulpi throws fire when she is above him or out of his reach and he has a clear line: a ball of flame
-- aimed at where she stands when it leaves his hand (so it can be dodged). His death is a scene: flyby 2 in the
-- cella, the controls taken away, bubbles.
local balls, flameT, flameN = {}, 0, 0
CDV.Loop(function()
    if true then return end                                  -- 20 Nov: the engine's boss throws his own fire
    if #balls > 0 and (CDV.Flag("turi_morto") or CDV.Flag("acqua")) then balls = {} end       -- he is gone: so is his fire
    for i = #balls, 1, -1 do
        local b = balls[i]
        b.t = b.t + 1
        local k = b.t / b.n
        local x, y, z = b.x0 + (b.x1 - b.x0) * k, b.y0 + (b.y1 - b.y0) * k - math.sin(k * math.pi) * 260, b.z0 + (b.z1 - b.z0) * k
        pcall(function()
            TEN.Effects.EmitFire(TEN.Vec3(x, y, z), 2)
            TEN.Effects.EmitLight(TEN.Vec3(x, y, z), TEN.Color(255, 140, 40), 9, false, "cdv_fiamma_" .. i)
        end)
        if b.t >= b.n then
            table.remove(balls, i)
            for j = 1, 5 do
                pcall(function() TEN.Effects.EmitFire(TEN.Vec3(x + math.random(-150, 150), y - math.random(0, 200), z + math.random(-150, 150)), 3) end)
            end
            CDV.Sfx(105)                                         -- it bursts
            local lp = Lara:GetPosition()
            if (lp.x - x) ^ 2 + (lp.z - z) ^ 2 < 480 ^ 2 and math.abs((lp.y - 400) - y) < 800 and Lara:GetHP() > 0 then
                Lara:SetHP(math.max(0, Lara:GetHP() - 150))
                CDV.Log("FLAME hit")
            end
        end
    end
    if not CDV.Flag("turi_sveglio") or CDV.Flag("turi_morto") or CDV.Flag("acqua") then return end
    local m = CDV.M("turi")
    if m == nil or not m:GetValid() or not m:GetActive() or m:GetHP() <= 0 or Lara:GetHP() <= 0 then return end
    flameT = flameT + 1
    if flameT < 75 then return end
    local tp, lp = m:GetPosition(), Lara:GetPosition()
    local flat = math.sqrt((tp.x - lp.x) ^ 2 + (tp.z - lp.z) ^ 2)
    if (lp.y < tp.y - 768 or flat > 4 * 1024) and flat < 16 * 1024 then
        local clear = true
        pcall(function()
            clear = TEN.Util.HasLineOfSight(m:GetRoomNumber(), TEN.Vec3(tp.x, tp.y - 700, tp.z), TEN.Vec3(lp.x, lp.y - 500, lp.z)) ~= false
        end)
        if clear then
            flameT = 0
            local d = math.sqrt(flat * flat + (tp.y - lp.y) ^ 2)
            balls[#balls + 1] = { x0 = tp.x, y0 = tp.y - 700, z0 = tp.z, x1 = lp.x, y1 = lp.y - 400, z1 = lp.z, t = 0, n = math.max(14, math.floor(d / 120)) }
            flameN = flameN + 1
            CDV.Sfx(563)                                         -- the roar of the flame
            CDV.Sfx(({ 737, 477, 496 })[flameN % 3 + 1])         -- and his shout
            if not CDV.Flag("turi_fuoco") then CDV.Flag("turi_fuoco", true); CDV.Log("FLAME first, " .. math.floor(d / 1024) .. " sectors") end
        end
    end
end)
CDV.Loop(function()
    if not CDV.Flag("turi_sveglio") or CDV.Flag("turi_scena") then return end
    local m = CDV.M("turi")
    local dead = CDV.Flag("turi_morto") == true or (m ~= nil and m:GetValid() and m:GetHP() <= 0)
    if not dead then return end
    CDV.Flag("turi_scena", true)
    CDV.Log("TURI dies: the scene")
    -- the camera: the level's fixed camera "cam_turi", put a sector and a half from him on a side with a clear line,
    -- a little above, in his room, and played on him every frame of the scene.
    local back, hold = nil, nil
    local okc, why = pcall(function()
        if m == nil or not m:GetValid() then return "no Turi" end
        local cam = TEN.Objects.GetCameraByName("cam_turi")
        if cam == nil then return "no camera cam_turi in this build of the level" end
        local p = m:GetPosition()
        local spot = nil
        for k = 0, 7 do
            local a = k * math.pi / 4
            local c = TEN.Vec3(math.floor(p.x + math.sin(a) * 1500), p.y - 1000, math.floor(p.z + math.cos(a) * 1500))
            local ok, los = pcall(function() return TEN.Util.HasLineOfSight(m:GetRoomNumber(), TEN.Vec3(p.x, p.y - 600, p.z), c) end)
            if ok and los == true then spot = c; break end
        end
        if spot == nil then spot = TEN.Vec3(p.x + 300, p.y - 1400, p.z + 300) end
        cam:SetPosition(spot)
        cam:SetRoomNumber(m:GetRoomNumber())
        hold = function() pcall(function() cam:Play(m) end) end
        hold()
        return "camera at " .. spot.x .. " " .. spot.y .. " " .. spot.z .. " room " .. m:GetRoomNumber()
    end)
    CDV.Log("TURI scene: " .. tostring(why))
    CDV.SceneOn = true
    CDV.Sfx(686)                                             -- Tony's death cry, at Lara: at his place it is too far to hear
    CDV.Quake(24)
    CDV.Say("Turi 'a Vulpi goes down with the temple he came to rob.", 6)
    local n = 0
    local function scene()
        n = n + 1
        pcall(TEN.Input.ClearAllKeys)
        if n < 180 then
            if hold then hold() end
        elseif n == 180 then
            CDV.SceneOn = false
            CDV.Log("TURI scene: camera back to Lara")
        end
        if n % 3 == 0 and m ~= nil and m:GetValid() then
            pcall(function()
                local p = m:GetPosition()
                TEN.Effects.EmitAirBubble(TEN.Vec3(p.x + math.random(-220, 220), p.y - math.random(200, 800), p.z + math.random(-220, 220)), 28, 48)
            end)
        end
        if n < 190 then CDV.After(1, scene) end
    end
    scene()
end)

